 d=json.loads(P.read_text());base=[x for x in d['layers'] if int(x['id'].split('-')[1])<251];later=[x for x in d['layers'] if int(x['id'].split('-')[1])>275];assert len(base)==250;d['layers']=sorted(base+B+later,key=lambda x:int(x['id'].split('-')[1]));assert len(B)==25 and len({x['id'] for x in d['layers']})==len(d['layers']);P.write_text(json.dumps(d,ensure_ascii=False,indent=2)+'\n');print(f"Wrote answer batch 10; total reviewed layers: {len(d['layers'])}")
